# -*- coding: utf-8 -*-
B=[
dict(a=1,z=2,star=2,
lit='「耶和華論到乾旱的話臨到耶利米：猶大哀哭，城門衰敗，眾人披上黑衣坐在地上；耶路撒冷的呼喊聲上達。」',
key=[('耶利米','H3414','yirmeyahu','耶和華高舉'),('乾旱','H1226','ha-batstorot','乾旱、缺水'),('悲哀','H56','avelah','哀悼'),('城門','H8179','she\'areha','城門'),('衰敗','H535','umlalu','衰弱、枯萎'),('黑衣','H6937','qadru','昏暗、披黑衣哀悼'),('呼喊','H6682','vetsvachat','哀號、呼喊')],
gram=['**{H1226}**（batstorot，乾旱）：這個字是複數，指「一連串的缺水」；在十七章八節也出現。這是一次**長期的大旱**，不是一季的缺雨。','**{H8179}**（sha\'ar，城門）：城門是古代城市的**法庭、市場與公共生活的中心**。「城門衰敗」是說整個城的生命在枯萎。**{H6682}**（tsevachah，呼喊）：這是受壓迫者的哭聲，如出埃及記裡以色列人的哀號。'],
exp=['這一章以**一場大旱**開始。「乾旱」是複數，意思是一連串缺水的日子。猶大哀哭，城門衰敗，人們披上黑衣，坐在地上，耶路撒冷的哀號聲上達天庭。','城門是古代城市的**中心**，是審判、買賣、聚會的地方。城門衰敗，意思是整個城市的生活都停了。**一場旱災，不只是缺水，而是整個社會的癱瘓。**','請留意：這一章的第一句是「耶和華論到乾旱的話」。旱災是神的話所要講的題目，不只是天氣。**神在苦難的現場，開口說話。**']),
dict(a=3,z=6,star=3,
lit='「貴族打發僕人去打水；他們來到水池，找不到水，就帶著空器皿回來，蒙羞受辱，抱頭而回。因為地上無雨，大地龜裂，耕地的人蒙羞，抱頭。田野的母鹿生下小鹿，也把牠丟棄，因為沒有青草。野驢站在光禿的高處，喘氣像野狗；因為沒有草，牠們的眼睛都失明了。」',
key=[('貴族','H117','adireihem','貴族、顯要的人'),('水池','H1356','gevim','水池、水溝'),('空','H7387','reqam','空空地'),('雨','H1653','geshem','大雨'),('母鹿','H365','ayyelet','母鹿'),('野驢','H6501','pera\'im','野驢'),('喘氣','H7602','sha\'afu','喘息')],
gram=['**{H7387}**（reqam，空空地）：「拿著空器皿」，這個字常用於形容**徒勞無功**，如賽五十五章十一節「我的話必不徒然返回」。**一個空空的水罐，是整個國家的縮影。**','**{H365}**（ayyelet，母鹿）：母鹿是出了名的**最慈愛的母親**（箴五章十九節）；連母鹿都棄子，是**自然秩序崩潰**的最後一道警鈴。'],
exp=['三到六節是一幅**一層一層向下的畫面**：先是貴族，再是僕人，再是耕地的，然後是母鹿，最後是野驢。從最有地位的人，到最卑微的動物，每一個都在受苦。旱災不看身份。','請看三節的細節：貴族打發僕人去打水，僕人帶著空器皿回來，抱著頭，蒙羞。一個空罐子，是一個很具體的失望。**我們常常以為只要有錢有人，就不會缺水；可是水不聽錢。**','五節是這一段最令人心酸的一句：田野的母鹿生下小鹿，就撇棄了，因為沒有草。母鹿是出了名最疼愛孩子的動物，連母鹿都棄子，這是**自然秩序崩潰的最後訊號**。六節的野驢站在光禿的高處，喘氣像野狗，眼睛都失明了。**整個大自然，都在代表人，向神呼求。**']),
dict(a=7,z=7,star=3,
lit='「耶和華啊，我們的罪孽雖然作見證控告我們，還是求你為你名的緣故行事；因為我們多次背道，得罪了你。」',
key=[('罪孽','H5771','avoneinu','罪孽'),('作見證','H6030','anu','回答、作見證'),('為你名','H4616','lema\'an shemekha','為了你的名'),('名','H8034','shemekha','你的名'),('背道','H4878','meshuvoteinu','背離、不信實'),('得罪','H2398','chatanu','犯罪')],
gram=['**{H4616}**（lema\'an，為了）與 **{H8034}**（shem，名）：「為你名的緣故」是舊約禱告最深的**根基**：我們不以自己的義為根據，而以神的名為根據。這是**詩篇二十五篇十一節、一百零九篇二十一節的同一句話**。','**{H4878}**（meshuvah，背道）：這個字是耶利米書三章六至十二節的「背道的以色列」同字根。這裡百姓**自己承認**。'],
exp=['七節是這一章的**第一個禱告**：「耶和華啊，我們的罪孽雖然作見證控告我們，還是求你為你名的緣故行事。」這是一個很誠實的禱告：他們不說「我們沒有錯」，而是承認：我們的罪孽在作見證告我們。','最重要的是下一句：**求你為你名的緣故行事。**這是舊約禱告最深的根基：我們求神，不是因為我們配，而是因為**祂的名**。神的名，代表祂的性情、祂的信實、祂的聲譽。我們把一切都放在祂的名上。','請留意：這個禱告，雖然誠實，卻有一個**微妙的問題**：百姓承認罪孽，但沒有說要悔改。這是接下來神的回應（十至十二節）的背景：**神要的，不只是認罪的話，而是回轉的心。**']),
dict(a=8,z=9,star=3,
lit='「以色列所盼望的，在患難時作他救主的啊，你為什麼在這地像寄居的，像行路的只住一宿呢？你為什麼像受驚的人，像不能救人的勇士呢？耶和華啊，你仍在我們中間；我們也被稱為你名下的人，求你不要離開我們。」',
key=[('盼望','H4723','miqveh','盼望、水池（同字）'),('救主','H3467','moshi\'o','拯救者'),('寄居的','H1616','ke-ger','寄居者、外人'),('行路的','H732','ke-orech','過路客'),('受驚的','H1724','nidham','驚呆'),('勇士','H1368','ke-gibbor','勇士'),('稱為','H7121','niqra','被稱呼')],
gram=['**{H4723}**（miqveh，盼望）：這個字是一個**雙關**：既是「盼望」，也是「水池」（十七章十三節說：耶和華是以色列的盼望，是活水的泉源）。在一場大旱裡，這個字的意思特別深：我們的「水池」是你。','**{H1616}**（ger，寄居者）：神被比作一位「寄居者」，是**在這地沒有根的人**，只住一晚，隨時要走。這是百姓對神最大的**恐懼**：祢是不是已經離開了？'],
exp=['八、九節是**一連串直率的問句**：你為什麼像寄居的？為什麼像受驚的？為什麼像不能救人的勇士？這些問句，聽起來有點冒犯，其實是**絕望中的誠實**。他們把心裡最深的懼怕說出來：神是不是離開了？','有一個很美的雙關：**「盼望」**（miqveh）這個字，同時也是「水池」。在一場大旱裡，他們呼求的「盼望」，同時就是「水池」。這是整章的**核心比喻**：我們真正的水池，是神自己。','九節的最後三句是禱告的重心：你仍在我們中間；我們是稱為你名下的人；求你不要離開我們。這是三個**根據**：祢的同在，祢的名，祢的子民。**在最乾旱的時候，這三個，是我們僅有的水源。**']),
dict(a=10,z=10,star=3,
lit='「耶和華對這百姓這樣說：這百姓喜愛飄蕩，不禁止自己的腳步，所以耶和華不喜悅他們；現在要記念他們的罪孽，追討他們的罪過。」',
key=[('喜愛','H157','ahavu','愛'),('飄蕩','H5128','la-nua','搖動、流浪'),('腳步','H7272','raglehem','腳'),('禁止','H2820','chasekhu','阻止、約束'),('不悅納','H7521','ratsam','喜悅、接納'),('記念','H2142','yizkor','記念、追討'),('罪孽','H5771','avonam','罪孽')],
gram=['**{H157}**（ahav，愛）與 **{H5128}**（nua，飄蕩）：「喜愛飄蕩」是一個**反諷**：百姓愛「到處亂走」，像迷路的羊。「不禁止腳步」是說他們不給自己設定界線。','**{H2142}**（zakhar，記念）：這個字本來是「**記得**」的意思。「記念他們的罪孽」，是說神把罪孽重新擺到面前。前面七節說「求你追念不要背約」，神回答：**我也追念，但是追念的是你們的罪。**'],
exp=['十節是神對百姓的**回應**，也是對七到九節禱告的**答覆**。神說：這百姓喜愛飄蕩，不禁止自己的腳步。他們的禱告很好聽，生活卻不改。**一個一邊禱告、一邊亂走的人，神不接納。**','請把這一節和七節放在一起：七節的百姓說：我們的罪孽作見證，求你為你名行事。十節的神說：我現在要記念他們的罪孽。他們沒有說錯，只是**沒有悔改**。承認罪，而不回轉，不是真的認罪。','這節讓人不舒服，也讓人誠實：**禱告若沒有生活，就是空的。**這與以賽亞書一章十五節的呼聲呼應：你們舉手禱告，我必遮眼不看。']),
dict(a=11,z=12,star=3,
lit='「耶和華對我說：不要為這百姓的好處祈禱。他們禁食的時候，我不聽他們的呼求；他們獻燔祭和素祭，我也不悅納；我卻要用刀劍、饑荒、瘟疫滅絕他們。」',
key=[('祈禱','H6419','titpallel','禱告、代求'),('為','H1157','be\'ad','為了'),('好處','H2896','le-tovah','為了好處'),('禁食','H6684','yatsumu','禁食'),('呼求','H7440','rinnatam','呼喊'),('燔祭','H5930','olah','燔祭'),('瘟疫','H1698','vedever','瘟疫')],
gram=['**{H6419}**（titpallel，代求）：這是「**不要為這百姓祈禱**」的第三次出現（七章十六節、十一章十四節、這裡，還有十五章一節的相關說法）。這一次，神加了「為他們的**好處**」（**{H2896}**）：不要為他們的平安順利代求。','**{H1698}**（dever，瘟疫）：「刀劍、饑荒、瘟疫」是耶利米書的**三聯審判**（二十一章七節、二十四章十節等），出現十五次以上。**這三樣是一組。**'],
exp=['十一、十二節是整章最**沉重**的一段：神再次對先知說，不要為這百姓祈禱求好處。他們禁食，我不聽；他們獻祭，我不悅納；我要用刀劍、饑荒、瘟疫滅絕他們。','這是**第三次**不准代求，我們要小心讀。請留意：神說的是「為他們的好處」，也就是**要求神免去審判的那種代求**。這在這一個**特定的歷史時刻**，是行不通的。這不是普遍原則：新約仍然教導我們為人代求（提前二章一節），連仇敵也要。','這兩節也讓我們看見一個很重要的真理：**宗教的動作，不能代替回轉。**禁食、獻祭，都是敬虔的形式，可是若心沒有回轉，神不悅納。這與撒母耳記上十五章二十二節的「聽命勝於獻祭」一致。']),
dict(a=13,z=14,star=3,
lit='「我說：唉，主耶和華啊，那些先知對他們說：你們不會看見刀劍，也不會遭遇饑荒，我必在這地方賜你們長久的平安。耶和華對我說：這些先知是託我的名說假預言；我沒有差遣他們，沒有吩咐他們，也沒有對他們說話；他們向你們預言的，是虛假的異象、占卜、虛無的事，和他們本心的詭詐。」',
key=[('平安','H7965','shalom','平安'),('真實','H571','emet','真實、穩固'),('異象','H2377','chazon','異象'),('占卜','H7081','qesem','占卜'),('虛無','H457','elil','虛無的事；偶像'),('詭詐','H8649','tarmit','詭詐')],
gram=['**{H7965}**（shalom，平安）與 **{H571}**（emet，真實）：假先知說「賜你們長久的平安」，原文是 **shalom emet**（真實的平安）。他們把「真實」用在假的平安上，是一個**諷刺**。','**{H2377}**（chazon，異象）、**{H7081}**（qesem，占卜）、**{H457}**（elil，虛無）、**{H8649}**（tarmit，詭詐）：這四個詞連用，是**假先知的資料來源**：不是從神那裡，而是從自己的心裡。申命記十八章十至二十二節已有類似的區分。'],
exp=['十三節是先知對神說的**一句為難的話**：唉，主耶和華啊，那些先知對他們說，你們不會看見刀劍，也不會遭遇饑荒。先知在為難：**你叫我說這些，可是別的先知說的卻是相反的。**聽眾要信誰呢？','十四節是神的回答，也是整本聖經對「假先知」最清楚的一段：**我沒有差遣他們，沒有吩咐他們，也沒有對他們說話。**他們的「異象」「占卜」「虛無」「詭詐」，都是**本心**出來的。這不是說他們故意說謊，而是說他們**說的是自己的心，不是神的話**。','這給了我們一個很實際的測驗：**一個信息，是從哪裡來的？**是從神的話，還是從人心？也要注意：這一段不是在鼓勵會眾去審判所有的教師，而是呼召每一位講說的人先問自己：我今天所說的，是神說的，還是我自己想說的？']),
dict(a=15,z=16,star=2,
lit='「所以耶和華這樣說：論到那些託我的名說預言的先知，我並沒有差遣他們，他們還說這地不會有刀劍和饑荒，其實那些先知必被刀劍和饑荒滅絕；聽他們預言的百姓，必因饑荒和刀劍被拋在耶路撒冷的街上，無人埋葬；他們、他們的妻子、兒女都是這樣；我必把他們的惡傾倒在他們身上。」',
key=[('滅絕','H8552','yitammu','終結、盡滅'),('拋','H7993','mushlakhim','被拋棄'),('街道','H2351','bechutsot','街道'),('埋葬','H6912','miqover','墳墓、葬埋'),('妻子','H802','nesheihem','他們的妻子'),('傾倒','H8210','veshafakhti','傾倒、澆灌')],
gram=['**{H7993}**（shalakh，拋）：「拋在街道上」是**最不得安葬**的結局，與八章一至二節呼應：連屍首也沒有尊嚴。','**{H8210}**（shafakh，傾倒）：「把他們的惡傾倒在他們身上」是一個**倒轉**：他們倒出了假話，現在假話倒回他們身上。'],
exp=['十五、十六節是對假先知的**審判**：他們說「這地不會有刀劍和饑荒」，結果他們自己被刀劍和饑荒滅絕。他們的話，正好成了**自己的墓誌銘**。','這裡有一個很重要的細節：**聽他們預言的百姓，也同樣被拋在街上**。假先知有罪，聽的人也不是無辜的。因為**人愛聽好聽的話**（提後四章三節），假先知才有市場。','最後一句是一個圖像：我必把他們的惡傾倒在他們身上。**人倒出來的，最後倒回自己身上。**這是整個聖經一個很深的原則：你種什麼，收什麼（加六章七節）。']),
dict(a=17,z=18,star=3,
lit='「你要對他們說這話：願我的眼睛晝夜流淚，不停止；因為我百姓的童女受了重大的破碎，受了極重的傷。我若出往田間，看哪，有被刀殺的；我若進入城裡，看哪，有因饑荒而患病的；連先知帶祭司，也在國中四處奔走，一無所知。」',
key=[('眼淚','H1832','dim\'ah','眼淚'),('破碎','H7667','shever','破碎、毀壞'),('童女','H1330','betulat','童女'),('重傷','H4347','makkah','創傷'),('被殺的','H2491','challei','被刺殺的'),('奔走','H5503','sachru','往來、經商')],
gram=['**{H7667}**（shever，破碎）：這是耶利米書的追蹤字，與四章六節、六章十四節、八章二十一節相同：「我百姓的破碎」。這是整卷書**先知與百姓一同破碎**的主旋律。','**{H1330}**（betulat，童女）：「我百姓的童女」是一個很溫柔的稱呼，指整個民族像一位**受傷的少女**，需要保護與憐惜。**{H5503}**（sachar，往來）：先知與祭司「往來」，也有「經商」的意思：他們在忙，卻**一無所知**。'],
exp=['十七節是先知對神**嚴厲的禁止之後**的回應：他沒有停止哭泣。神說「不要為這百姓代求」，可是先知說：願我的眼睛晝夜流淚。**他不能禱告求免去審判，卻仍然可以哭泣。**這是一個很深的真理：有些時候，眼淚就是我們的禱告。','請留意這個稱呼：**「我百姓的童女」**。先知把整個民族，比作一位受傷的少女。他看見的不是一個該被處罰的群體，而是一位**受了重傷、需要憐惜的女兒**。**這就是牧者的心。**','十八節是現場的描述：田間有被刀殺的，城裡有因饑荒患病的；先知與祭司在國中奔走，卻一無所知。**最忙的人，不一定最明白。**這是對所有帶領者的提醒：忙碌不等於有洞察。']),
dict(a=19,z=20,star=3,
lit='「你全然棄絕猶大嗎？你心裡厭惡錫安嗎？為什麼擊打我們，使我們無法醫治呢？我們盼望平安，卻沒有好處；盼望得醫治的時候，卻是驚惶。耶和華啊，我們承認自己的邪惡，也承認我們列祖的罪孽，因為我們得罪了你。」',
key=[('厭惡','H1602','ga\'alah','厭棄、嫌惡'),('擊打','H5221','hikkitanu','擊打'),('醫治','H4832','marpe','醫治'),('盼望','H6960','qavoh','等候、盼望'),('驚惶','H1205','be\'atah','驚恐'),('邪惡','H7562','rashanu','行惡'),('罪孽','H5771','avon','罪孽')],
gram=['**{H6960}**（qavah，等候、盼望）：這個字的本義是「**繩子被拉緊**」，指**緊張而滿懷期待地等候**。十九節的「我們盼望平安」與二十二節的「我們仍要等候你」用同一個字根。','**{H7562}**（rasha，行惡）：這是「惡人」（**resha\'im**）的動詞形。與十二章一節「惡人為何亨通」相呼應：**這一次，說「我們行了惡」的，不是別人，是百姓自己。**'],
exp=['十九、二十節是**百姓第二次禱告**，與七到九節不同：這一次，他們提出的是一連串直率的問題：你全然棄絕猶大嗎？你心裡厭惡錫安嗎？為什麼擊打我們，使我們無法醫治呢？這是從絕望裡發出的呼喊。','請看這個轉折：十九節是**質問**，二十節是**認罪**。「耶和華啊，我們承認自己的邪惡，也承認我們列祖的罪孽，因為我們得罪了你。」這是一個**更深的認罪**：不只認自己的罪，也認先祖的罪。這是代表性的認罪（尼希米記一章六至七節、但以理書九章）。','從七節到二十節，百姓的禱告在**慢慢變得更誠實**。第一次是「我們的罪孽作見證」，第二次是「我們承認自己的邪惡」。**真正的認罪，不是說「我犯罪了」，而是說「我是這樣的人」。**']),
dict(a=21,z=22,star=3,
lit='「求你為你名的緣故，不要厭棄我們，不要使你榮耀的寶座受辱；求你記念，不要廢棄你與我們所立的約。外邦人虛無的神中，有能降雨的嗎？天能自己降下甘霖嗎？耶和華我們的神啊，不是你嗎？所以我們要等候你，因為這一切都是你所造的。」',
key=[('厭棄','H5006','tin\'atz','輕視、拒絕'),('寶座','H3678','kise','寶座'),('記念','H2142','zekhor','記念'),('約','H1285','briterkha','你的約'),('虛無','H1892','be-havlei','虛無、一口氣'),('等候','H6960','ve-nequveh','等候、盼望')],
gram=['**{H2142}**（zakhar，記念）：「求你記念」是對神的呼喊，與十節神的「記念他們的罪孽」形成對比：**神記念罪，也可以記念約。**百姓求神，不是記念他們的行為，而是記念**祂自己的約**。','**{H6960}**（qavah，等候）：這個字與十九節的「盼望」同字根，是這一章的**最後一個詞**：「我們仍要等候你」。**整章的結尾，不是一個解決，而是一種等待。**'],
exp=['二十一節是整章**第三個、也是最美的禱告**。不再是「我們有什麼好處」，而是：求你為你名的緣故，求你記念你的約。這是整本聖經最古老、最穩固的根基：**神的名，神的約。**','二十二節是整章的**結論**：外邦人虛無的神中，有能降雨的嗎？天能自己降下甘霖嗎？不是你嗎？他們在一場旱災裡，看清了誰是真神：**能降雨的，只有耶和華。**','這一章的結尾，是一個很美的詞：「**等候**」。他們沒有得到答案，沒有得到雨，卻說：我們仍要等候你，因為一切都是你所造的。**這是信心最深的樣子：在沒有答案的時候，仍然把盼望放在創造者身上。**']),
]
